import{_ as n,o as e,c as a,ag as t}from"./chunks/framework.QfQ7DfGu.js";const c=JSON.parse('{"title":"龙芯开源社区","description":"","frontmatter":{"title":"龙芯开源社区","outline":"deep"},"headers":[],"relativePath":"repos/loongson-community.md","filePath":"repos/loongson-community.md"}'),r={name:"repos/loongson-community.md"};function l(i,o,s,h,m,u){return e(),a("div",null,[...o[0]||(o[0]=[t('<h1 id="开源平台" tabindex="-1">开源平台 <a class="header-anchor" href="#开源平台" aria-label="Permalink to &quot;开源平台&quot;">​</a></h1><h2 id="openharmony-loongarch" tabindex="-1">OpenHarmony-LoongArch <a class="header-anchor" href="#openharmony-loongarch" aria-label="Permalink to &quot;OpenHarmony-LoongArch&quot;">​</a></h2><p>该仓库介绍龙开源鸿蒙(OHOS)龙架构(LoongArch)主线移植项目。</p><p>网址链接：<a href="https://gitee.com/openharmony-loongarch" target="_blank" rel="noreferrer">https://gitee.com/openharmony-loongarch</a></p><h2 id="loongson" tabindex="-1">Loongson <a class="header-anchor" href="#loongson" aria-label="Permalink to &quot;Loongson&quot;">​</a></h2><p>龙芯官方帐号，支持并维护多个开源项目，包括有：</p><ul><li>Firmware，维护、更新和发布固件。</li><li>GCC，提供编译器维护与更新。</li><li>QEMU，提供 LoongArch 架构支持。</li></ul><p>以及其他开源软件和工具。</p><p>Github 主页链接：<a href="https://github.com/loongson" target="_blank" rel="noreferrer">https://github.com/loongson</a></p><p>Gitee 主页链接：<a href="https://gitee.com/loongson" target="_blank" rel="noreferrer">https://gitee.com/loongson</a></p><h2 id="loongson-community" tabindex="-1">Loongson Community <a class="header-anchor" href="#loongson-community" aria-label="Permalink to &quot;Loongson Community&quot;">​</a></h2><p>龙芯开源社区在 Github 中的帐号，支持并维护多个开源项目，包括有：</p><ul><li>Loongoffice，更新和维护开源办公处理软件。</li><li>open-la500，更新和维护 LoongArch 架构下的开源处理器。</li><li>U-boot，维护开发固件。</li></ul><p>以及其他开源软件和工具。</p><p>帐号主页链接：<a href="https://github.com/loongson-community" target="_blank" rel="noreferrer">https://github.com/loongson-community</a></p><h2 id="loongson-edu" tabindex="-1">Loongson-Edu <a class="header-anchor" href="#loongson-edu" aria-label="Permalink to &quot;Loongson-Edu&quot;">​</a></h2><p>龙芯教育开源仓库，主要提供基于 la32r 指令的教育生态技术支持，包括有：</p><ul><li>la32r-toolchains ，面向 la32r 指令集的交叉编译器。</li><li>la32r-linux，基于 la32r 的 linux 内核。</li><li>la32r-uboot，基于 la32r 的系统固件。</li></ul><p>以及其他面向 la32r 的软件和工具。</p><p>帐号主页链接：<a href="https://gitee.com/loongson-edu" target="_blank" rel="noreferrer">https://gitee.com/loongson-edu</a></p><h2 id="loongson-cloud-community" tabindex="-1">Loongson-Cloud-Community <a class="header-anchor" href="#loongson-cloud-community" aria-label="Permalink to &quot;Loongson-Cloud-Community&quot;">​</a></h2><p>龙芯云社区，主要支持并维护 LoongArch 架构下云相关的软件与服务，包括有：</p><ul><li>k3s</li><li>docker-library</li><li>kafka</li></ul><p>以及其他面向云生态的应用软件</p><p>帐号主页链接：<a href="https://github.com/Loongson-Cloud-Community" target="_blank" rel="noreferrer">https://github.com/Loongson-Cloud-Community</a></p>',25)])])}const g=n(r,[["render",l]]);export{c as __pageData,g as default};
